import limited_client as robot, numpy as np
for c in ['topview','corner','corner2','corner3','corner4','behindGripper','gripperPOV']:
 o=robot.observe(c); a=o['rgb']; d=o['depth_m'];
 m=(a[:,:,0]>140)&(a[:,:,0]>a[:,:,1]*1.5)&(a[:,:,1]>a[:,:,2]*1.25)&(a[:,:,1]<180)
 ys,xs=np.where(m)
 print('\n',c,'pixels',len(xs),'bbox', (xs.min(),ys.min(),xs.max(),ys.max()) if len(xs) else None,'cam',np.round(o['camera_to_world'][:3,3],3))
 if len(xs):
  x=int(xs.mean());y=int(ys.mean()); print('centroid',x,y,'depth',d[y,x], 'mat',np.round(o['camera_to_world'],3).tolist())
PY

